INSERT INTO public.blog_categories (id, name, headline, intro, icon, tone, position) VALUES
    ('product', 'Product updates', 'What changed in ASComply.', 'New features and changes to the platform, with what they mean for your invoices.', 'package', 0, 1),
    ('regulation', 'Regulation & FIRS news', 'The rules, explained plainly.', 'What Nigeria''s e-invoicing rollout asks of your business, and when.', 'landmark', 1, 2),
    ('customers', 'Customer stories', 'How businesses prepared.', 'Finance teams and firms describe how they moved their invoices onto a clearance workflow.', 'building-2', 2, 3),
    ('company', 'Company news', 'News from the team.', 'Pilots, offices, offers and people at ASComply.', 'megaphone', 3, 4),
    ('partners', 'Partner announcements', 'Who we work with.', 'Connectors, SI/APP partners and the consultants who implement ASComply.', 'handshake', 4, 5),
    ('engineering', 'Engineering', 'How it is built.', 'Notes from the engineers on rule sets, submissions and the audit log.', 'code-xml', 5, 6);
INSERT INTO public.blog_posts (id, category_id, publish_date, title, summary, body) VALUES
    ('fifty-more-pilot', 'company', '2026-10-14', 'The private pilot opens to 20 more businesses', 'A second cohort joins the 90-day private pilot in November. Applications close on 7 November.', '[{"type":"p","text":"The first cohort of the private pilot finished in September. Twelve businesses ran their live invoices through ASComply for 90 days, alongside their existing process. We are now opening 20 places for a second cohort, starting in November."},{"type":"h","text":"Who the pilot is for"},{"type":"p","text":"The pilot suits businesses that issue at least a few hundred invoices a month and want to test clearance before it applies to them. Accounting & tax firms can apply on behalf of up to five clients."},{"type":"ul","items":["A named onboarding contact for the full 90 days","Connection to your accounting system, or file imports if you prefer","A readiness report at the end of the pilot"]},{"type":"h","text":"How to apply"},{"type":"p","text":"Apply through the form on ascomply.com. We review every application and reply within five working days."},{"type":"note","kind":"deadline","title":"Applications close on 7 November 2026","text":"The second cohort starts on 17 November. Late applications go to the waiting list for the next cohort."}]'::jsonb),
    ('what-changes', 'regulation', '2026-10-09', 'What structured e-invoicing changes for a Nigerian finance team', 'Invoices stop being documents you send and become records FIRS clears. Here is what that means day to day.', '[{"type":"p","text":"Under structured e-invoicing, an invoice is valid once FIRS has cleared it. That moves checks that used to happen at month end, or at audit, to the moment the invoice is issued."},{"type":"h","text":"The invoice becomes a checkpoint"},{"type":"p","text":"Each invoice is prepared in a required format, signed, submitted and given a clearance reference. An invoice with a wrong TIN or a tax total that does not add up is rejected, and has to be fixed before it counts."},{"type":"note","kind":"regulation","title":"Clearance applies per invoice","text":"The obligation is on each invoice, not on a monthly return. A rejected invoice is not a valid invoice until it is corrected and cleared."},{"type":"h","text":"What your team does differently"},{"type":"ul","items":["Customer TINs are checked before invoices are issued","Approvals happen before submission, not after payment","Clearance references are kept with every invoice"]},{"type":"p","text":"The demo below shows an approved invoice moving through submission to a recorded outcome."},{"type":"demo","demo":"clearance"},{"type":"h","text":"Where to start"},{"type":"p","text":"Start with your customer records. Most rejections we see trace back to a missing or badly formatted TIN, and those are fixed once in the accounting system rather than on every invoice."}]'::jsonb),
    ('recognition-learns', 'product', '2026-10-02', 'Document recognition now learns each supplier layout', 'Correct a field once and the next invoice from that supplier is read correctly the first time.', '[{"type":"p","text":"Document recognition reads PDFs, scans and photos into invoice fields. From this release, it also remembers where each supplier puts each field."},{"type":"h","text":"What changed"},{"type":"p","text":"When you correct a field during review, the position is saved against that supplier''s layout. The next invoice in the same layout is read using the saved position."},{"type":"ul","items":["Learning is per supplier layout, not shared across suppliers","Every correction is recorded in the audit trail","An admin can reset a layout from the supplier record"]},{"type":"h","text":"What you will notice"},{"type":"p","text":"Fewer fields flagged for review on repeat suppliers. In the pilot, the share of fields needing review on a supplier''s third invoice fell to under a quarter of the first."},{"type":"note","kind":"product","title":"Available to all workspaces","text":"No setup is needed. Learning starts with the next correction you make."}]'::jsonb),
    ('sage-connector', 'partners', '2026-09-24', 'The Sage connector is now available', 'Invoices flow in from Sage and clearance references are written back to the ledger.', '[{"type":"p","text":"Businesses on Sage can now connect it directly to ASComply. Invoices arrive without exports, and clearance results are written back to the matching ledger entry."},{"type":"h","text":"How it works"},{"type":"p","text":"An admin authorises the connection from Settings. New invoices are picked up every few minutes, validated and routed through your approval workflow."},{"type":"ul","items":["Sage remains the source of truth for your ledger","Customer records sync and are checked for a valid TIN","Clearance references appear on the invoice in Sage"]},{"type":"h","text":"Other systems"},{"type":"p","text":"Connectors for Odoo, QuickBooks, SAP and Microsoft Dynamics are in progress. Until then, those systems use file imports."}]'::jsonb),
    ('phased-rollout', 'regulation', '2026-09-18', 'How the phased rollout works, and where your company sits', 'Large taxpayers went first. Here is how to work out when the requirement reaches you.', '[{"type":"p","text":"Structured e-invoicing in Nigeria is being introduced in phases, starting with large taxpayers and moving to medium and then smaller businesses."},{"type":"h","text":"Find your phase"},{"type":"p","text":"Your phase depends on how FIRS classifies your business by size. Your tax adviser or your tax office can confirm the classification."},{"type":"note","kind":"deadline","title":"Confirm your onboarding window","text":"Each phase has its own onboarding window. Check the current dates on the FIRS portal or with your adviser, as they have moved before."},{"type":"h","text":"What to do before your window opens"},{"type":"ul","items":["Clean up customer TINs and addresses","Decide who approves invoices and at what amount","Choose how invoices will reach the clearance system"]},{"type":"p","text":"A readiness assessment covers all three in 14 days."}]'::jsonb),
    ('approval-thresholds', 'product', '2026-09-11', 'Approval workflows with amount thresholds', 'Route invoices over a set amount to a second approver, and test the workflow before turning it on.', '[{"type":"p","text":"Approval workflows can now branch on the invoice amount. Invoices over a threshold go to an extra approver; smaller ones pass with one approval."},{"type":"h","text":"Setting a threshold"},{"type":"p","text":"Add an amount check to any workflow, choose the threshold and the approver for each path. Approvers can be people or roles."},{"type":"demo","demo":"approval"},{"type":"h","text":"Testing before you go live"},{"type":"p","text":"Enter a sample amount to see which path an invoice would take. The workflow only applies to new invoices once you turn it on."}]'::jsonb),
    ('sealed-rules', 'engineering', '2026-09-04', 'Why our rule sets are sealed once active', 'If a rule changed after the fact, a passed invoice could quietly become a failed one. Sealing prevents that.', '[{"type":"p","text":"Every validation result in ASComply records the rule set version it ran against. Once a version is active, it cannot be edited."},{"type":"h","text":"The problem with editable rules"},{"type":"p","text":"If rules could change in place, re-opening an old invoice could show a different result from the one your team saw when they approved it. An auditor would have no way to tell which was true."},{"type":"h","text":"How versions work"},{"type":"ul","items":["A new version is drafted, reviewed and then activated","Results always name the version they ran against","A single rule can be paused without a new version, and the pause is logged"]},{"type":"p","text":"This keeps the past stable while still letting admins respond quickly to a rule that misfires."}]'::jsonb),
    ('lagos-office', 'company', '2026-08-27', 'We have opened an office in Lagos', 'Onboarding and support now work from Victoria Island, in the same time zone as our customers.', '[{"type":"p","text":"Our onboarding and support team has moved into a permanent office on Victoria Island, Lagos."},{"type":"h","text":"What it means for customers"},{"type":"p","text":"Onboarding sessions can now be held in person, and support hours match the Nigerian working day."},{"type":"ul","items":["Support from 8:00 to 18:00 WAT, Monday to Friday","In-person onboarding for pilot customers in Lagos","A training room for accounting & tax firms"]}]'::jsonb),
    ('tin-errors', 'regulation', '2026-08-20', 'The five validation errors we see most often', 'Most rejected invoices fail for one of five reasons. All five can be fixed before submission.', '[{"type":"p","text":"Across pilot invoices, five checks account for most failures. None needs a change of process, only cleaner data."},{"type":"h","text":"The five"},{"type":"ul","items":["Buyer TIN missing or in the wrong format","VAT not equal to 7.5% of the taxable amount","Line totals that do not add up to the invoice total","Buyer address incomplete","Issue date in the future"]},{"type":"h","text":"Fixing them at the source"},{"type":"p","text":"The first and fourth are customer data problems. Fix them in the accounting system and every future invoice is correct."},{"type":"note","kind":"regulation","title":"VAT rate","text":"The standard VAT rate used in these checks is 7.5%. Exempt and zero-rated lines are handled by their own rules."}]'::jsonb),
    ('submission-retries', 'engineering', '2026-08-13', 'Retrying submissions without sending an invoice twice', 'A timeout does not tell you whether FIRS received the invoice. Here is how we retry safely.', '[{"type":"p","text":"When a submission times out, there are two possibilities: FIRS never received it, or it did and the response was lost. Retrying blindly risks a duplicate."},{"type":"h","text":"Checking before retrying"},{"type":"p","text":"Each submission carries a stable identifier. Before a retry, ASComply asks for the status of that identifier and only resubmits if FIRS has no record of it."},{"type":"h","text":"What your team sees"},{"type":"ul","items":["A connection failure shows as Retrying, not Rejected","No action is needed unless retries are exhausted","Every attempt is recorded in the audit trail"]}]'::jsonb),
    ('firm-portfolio', 'customers', '2026-08-06', 'How an accounting firm runs 40 clients from one portfolio', 'Okafor & Bello moved its client invoicing checks into a single portfolio view during the pilot.', '[{"type":"p","text":"Okafor & Bello Chartered Accountants advises around 40 businesses in Lagos and Abuja. Before the pilot, each client''s invoice checks lived in a different spreadsheet."},{"type":"h","text":"One list, sorted by readiness"},{"type":"p","text":"The partners now start each week from the portfolio, which shows each client''s readiness score and what needs attention."},{"type":"quote","text":"We stopped asking clients for their invoices. We can see which ones need us before they call.","who":"Ngozi Okafor, Partner, Okafor & Bello"},{"type":"h","text":"What they changed"},{"type":"ul","items":["Each client has its own rules and approvers","Junior staff fix validation errors; partners approve","Evidence bundles go to clients at month end"]}]'::jsonb),
    ('csv-import', 'product', '2026-07-30', 'Import from CSV or Excel, with saved column mappings', 'Upload an export from your accounting system and get one invoice per row. The mapping is remembered.', '[{"type":"p","text":"Not every accounting system has a connector yet. File import covers the gap: upload a CSV or Excel export and ASComply creates one invoice per row."},{"type":"h","text":"How it works"},{"type":"demo","demo":"import"},{"type":"p","text":"Columns are matched to invoice fields automatically. If a match is wrong, change it once and the mapping is saved for the next file from the same system."},{"type":"h","text":"Rows that cannot be read"},{"type":"p","text":"Rows with missing or unreadable values are listed with the reason, so you can fix them in the source and import again."}]'::jsonb),
    ('si-app-partners', 'partners', '2026-07-23', 'Working with SI/APP partners on transmission', 'ASComply prepares and approves invoices. Licensed partners transmit them. Here is how the two connect.', '[{"type":"p","text":"Invoices reach FIRS through licensed system integrators and access point providers. ASComply works alongside them rather than replacing them."},{"type":"h","text":"Who does what"},{"type":"ul","items":["ASComply validates, routes for approval and archives","The SI/APP partner transmits and returns the clearance response","Your accounting system keeps the ledger"]},{"type":"h","text":"Choosing a partner"},{"type":"p","text":"If you already have a partner, we connect to them. If not, we can introduce you to partners we have tested with."}]'::jsonb),
    ('lagos-freight', 'customers', '2026-07-16', 'Lagos Freight cut rejected submissions during the pilot', 'A logistics company with 60 invoices a week fixed most errors before they reached FIRS.', '[{"type":"p","text":"Lagos Freight & Logistics issues around 60 invoices a week to shippers and importers. In the first fortnight of the pilot, a third failed at least one check."},{"type":"h","text":"Where the errors came from"},{"type":"p","text":"Most failures traced back to customer records created years ago without a TIN. The team fixed them in their accounting system over two weeks."},{"type":"quote","text":"The validation messages told us exactly which field was wrong. We did not need a consultant to read them.","who":"Finance manager, Lagos Freight & Logistics"},{"type":"h","text":"By the end of the pilot"},{"type":"p","text":"Fewer than one invoice in twenty needed a correction before submission, and none was rejected for a TIN error in the final month."}]'::jsonb),
    ('evidence-bundles', 'product', '2026-06-25', 'Evidence bundles for auditors', 'Export one invoice with its source document, checks, approvals and clearance response as a single package.', '[{"type":"p","text":"Auditors ask for the same things on every invoice they sample. An evidence bundle packages them in one file."},{"type":"h","text":"What is in a bundle"},{"type":"ul","items":["The original document as received","Validation results and the rule set version","Each approval, with who and when","The clearance response from FIRS"]},{"type":"p","text":"Bundles can be exported one at a time or for every invoice in a period."}]'::jsonb),
    ('readiness-assessment', 'company', '2026-06-18', 'Introducing the 14-day readiness assessment', 'A fixed-scope review of your invoice data, approvals and connection to the clearance system.', '[{"type":"p","text":"The readiness assessment is a 14-day review that tells you what needs to change before structured e-invoicing applies to your business."},{"type":"h","text":"What we review"},{"type":"ul","items":["A sample of recent invoices against the current rule set","Customer and supplier records","Who approves invoices today, and how","How invoices will reach the clearance system"]},{"type":"h","text":"What you receive"},{"type":"p","text":"A written report with each finding, its effect on clearance and the fix. Your adviser can attend the closing session."}]'::jsonb),
    ('records-retention', 'regulation', '2026-05-28', 'Keeping invoice records: what to archive and for how long', 'Clearance does not end your record-keeping obligations. Here is what to keep alongside each invoice.', '[{"type":"p","text":"A cleared invoice still needs to be kept, along with the evidence that it was cleared."},{"type":"h","text":"What to keep"},{"type":"ul","items":["The invoice as cleared, in the submitted format","The clearance reference and response","Any credit notes that amend it"]},{"type":"note","kind":"regulation","title":"Retention period","text":"Nigerian tax records are generally kept for at least six years. Confirm the period that applies to your business with your adviser."},{"type":"h","text":"Where to keep it"},{"type":"p","text":"ASComply archives each cleared invoice with its evidence. You can export the archive at any time."}]'::jsonb),
    ('audit-log', 'engineering', '2026-05-14', 'An audit log that cannot be edited', 'Every action is appended, never changed. Here is how we keep it that way.', '[{"type":"p","text":"The audit trail records every import, edit, approval and submission. Entries can be added but never changed or removed, including by our own staff."},{"type":"h","text":"How it is stored"},{"type":"p","text":"Each entry includes a hash of the one before it. Changing any entry would break the chain from that point on, and the break is detected on read."},{"type":"h","text":"What it records"},{"type":"ul","items":["Who acted, or that the system did","What changed, with before and after values","When, to the second, in WAT"]}]'::jsonb),
    ('consultant-programme', 'partners', '2026-04-30', 'A partner programme for ERP & accounting consultants', 'Consultants who implement Odoo, Sage and SAP can now offer ASComply to their clients.', '[{"type":"p","text":"Many businesses will prepare for e-invoicing with the consultant who set up their accounting system. The partner programme gives those consultants training and a sandbox."},{"type":"h","text":"What partners get"},{"type":"ul","items":["A sandbox workspace with sample companies","Training on connectors and rule sets","A named contact for implementation questions"]},{"type":"p","text":"Applications are open on ascomply.com."}]'::jsonb),
    ('sahara-foods', 'customers', '2026-04-16', 'Sahara Foods clears its first month without re-keying', 'A food distributor moved from typing invoices into a portal to approving them in one queue.', '[{"type":"p","text":"Sahara Foods Distribution issues around 480 invoices a month. Before ASComply, a finance officer re-keyed each one into a separate portal."},{"type":"h","text":"What changed"},{"type":"p","text":"Invoices now arrive from their accounting system, are checked against the rule set and wait in one approval queue for the finance director."},{"type":"quote","text":"The month-end rush is gone. Invoices are cleared the day they are issued.","who":"Finance director, Sahara Foods Distribution"},{"type":"h","text":"The numbers"},{"type":"ul","items":["482 invoices processed in the first full month","94% passed every check first time","12 needed attention, all fixed the same week"]}]'::jsonb);
